insert into materiais (turma_id, autor, materia, titulo, status, questoes, publicado_em)
select t.id, (select tp.professor_id from turma_professores tp where tp.turma_id = t.id limit 1), 'mt', 'Diagnóstico de largada: Matemática', 'publicado', $j$[{"id": "d1", "tipo": "mc", "habilidade": "Valor posicional", "enunciado": "No número <b>4.736</b>, quanto vale o algarismo 7?", "resposta": "700", "alternativas": ["700", "7", "70", "7.000"], "explicacao": "O 7 está na casa das centenas: vale 700.", "tutor": {"alternativas": {"7": "Esse é o valor absoluto. Na casa das centenas, o 7 vale 7 × 100.", "70": "70 seria se o 7 estivesse na casa das dezenas.", "7.000": "7.000 seria se o 7 estivesse na casa do milhar."}, "pontos": ["Valor posicional = algarismo × valor da casa (unidade, dezena, centena…)."], "pegadinha": "O mesmo algarismo vale coisas diferentes conforme a posição."}}, {"id": "d2", "tipo": "mc", "habilidade": "Ordem das operações", "enunciado": "Quanto é <b>8 + 2 × 5</b>?", "resposta": "18", "alternativas": ["18", "50", "15", "10"], "explicacao": "Primeiro 2 × 5 = 10, depois 8 + 10 = 18.", "tutor": {"alternativas": {"50": "Você somou primeiro (8 + 2 = 10) e depois multiplicou. A multiplicação vem antes.", "15": "Você somou tudo (8 + 2 + 5). O sinal é de vezes.", "10": "10 é só 2 × 5; faltou somar o 8."}, "pontos": ["Ordem: parênteses → potências → × e ÷ → + e −."], "pegadinha": "Não se resolve sempre da esquerda para a direita."}}, {"id": "d3", "tipo": "mc", "habilidade": "Frações equivalentes", "enunciado": "Qual fração é <b>equivalente</b> a 2/3?", "resposta": "4/6", "alternativas": ["4/6", "3/4", "2/6", "4/3"], "explicacao": "2/3 × 2/2 = 4/6: mesma parte do inteiro.", "tutor": {"alternativas": {"3/4": "Você somou 1 em cima e embaixo. Equivalência é multiplicar os dois pelo mesmo número.", "2/6": "Mudou só o denominador: a fração ficou menor.", "4/3": "Multiplicou só o numerador: a fração ficou maior que 1."}, "pontos": ["Fração equivalente: multiplique (ou divida) numerador e denominador pelo mesmo número."], "pegadinha": "Somar o mesmo número em cima e embaixo NÃO gera fração equivalente."}}, {"id": "d4", "tipo": "mc", "habilidade": "Comparação de frações", "enunciado": "Qual é maior: <b>1/3</b> ou <b>1/5</b>?", "resposta": "1/3", "alternativas": ["1/3", "1/5", "são iguais", "não dá para comparar"], "explicacao": "Dividir em 3 dá pedaços maiores que dividir em 5.", "tutor": {"alternativas": {"1/5": "Erro clássico: denominador maior quer dizer pedaços MENORES.", "são iguais": "O numerador é igual, mas os pedaços têm tamanhos diferentes.", "não dá para comparar": "Dá: com o mesmo numerador, vence o menor denominador."}, "pontos": ["Mesmo numerador: maior a fração com MENOR denominador.", "Mesmo denominador: maior a fração com MAIOR numerador."], "pegadinha": "5 é maior que 3, mas 1/5 é menor que 1/3."}}, {"id": "d5", "tipo": "mc", "habilidade": "Comparação de decimais", "enunciado": "Qual número é o <b>maior</b>?", "resposta": "0,5", "alternativas": ["0,5", "0,45", "0,125", "0,09"], "explicacao": "Iguale as casas: 0,50 > 0,45 > 0,125 > 0,09.", "tutor": {"alternativas": {"0,45": "Mais algarismos não quer dizer maior: 0,5 = 0,50, que é mais que 0,45.", "0,125": "Tem mais casas, mas vale só um oitavo.", "0,09": "0,09 são nove centésimos, bem menos que meio."}, "pontos": ["Para comparar decimais, iguale o número de casas com zeros."], "pegadinha": "Achar que 0,45 é maior que 0,5 porque 45 > 5."}}, {"id": "d6", "tipo": "mc", "habilidade": "Porcentagem", "enunciado": "Quanto é <b>25% de 80</b>?", "resposta": "20", "alternativas": ["20", "25", "55", "32"], "explicacao": "25% = 1/4. 80 ÷ 4 = 20.", "tutor": {"alternativas": {"25": "Você repetiu a porcentagem; 25% é uma parte de 80.", "55": "Você subtraiu 25 de 80. Porcentagem é uma fração do total.", "32": "Conta errada: 25% é um quarto, e 80 ÷ 4 = 20."}, "pontos": ["25% = 1/4 · 50% = 1/2 · 10% = 1/10."], "pegadinha": "Porcentagem não se subtrai do número: é uma parte dele."}}, {"id": "d7", "tipo": "mc", "habilidade": "MMC em problema", "enunciado": "Um ônibus sai a cada 6 minutos e outro a cada 8. Saíram juntos agora. Em quantos minutos <b>sairão juntos de novo</b>?", "resposta": "24", "alternativas": ["24", "48", "14", "2"], "explicacao": "Múltiplos de 6: 6, 12, 18, 24. De 8: 8, 16, 24. O primeiro em comum é 24.", "tutor": {"alternativas": {"48": "48 também é múltiplo comum, mas não o primeiro (menor).", "14": "Você somou 6 + 8. O certo é o menor múltiplo comum.", "2": "2 é o MDC (maior divisor comum), não o múltiplo."}, "pontos": ["\"Juntos de novo\", \"ao mesmo tempo\" → MMC.", "\"Dividir em partes iguais, o maior possível\" → MDC."], "pegadinha": "Confundir MMC com MDC. A pista está na pergunta."}}, {"id": "d8", "tipo": "mc", "habilidade": "Área × perímetro", "enunciado": "Um retângulo mede 5 cm por 3 cm. Qual é a sua <b>área</b>?", "resposta": "15 cm²", "alternativas": ["15 cm²", "16 cm", "8 cm²", "15 cm"], "explicacao": "Área do retângulo = base × altura = 5 × 3 = 15 cm².", "tutor": {"alternativas": {"16 cm": "16 cm é o perímetro (soma dos quatro lados), não a área.", "8 cm²": "Você somou só dois lados (5 + 3).", "15 cm": "O número está certo, mas área se mede em cm² (centímetros quadrados)."}, "pontos": ["Área: o que cabe dentro (cm²). Perímetro: o contorno (cm)."], "pegadinha": "Trocar área por perímetro é o erro mais comum de geometria."}}, {"id": "d9", "tipo": "mc", "habilidade": "Potência", "enunciado": "Quanto é <b>2³</b>?", "resposta": "8", "alternativas": ["8", "6", "9", "5"], "explicacao": "2³ = 2 × 2 × 2 = 8.", "tutor": {"alternativas": {"6": "Você multiplicou 2 × 3. Potência é 2 × 2 × 2.", "9": "Inverteu: 3² = 9. O 2 é a base e o 3 é o expoente.", "5": "Você somou 2 + 3."}, "pontos": ["Expoente = quantas vezes a base se multiplica por ela mesma."], "pegadinha": "2³ não é 2 × 3."}}, {"id": "d10", "tipo": "mc", "habilidade": "Divisão com resto", "enunciado": "32 alunos vão viajar de van, e cada van leva 6. Quantas vans são <b>necessárias</b>?", "resposta": "6", "alternativas": ["6", "5", "5,3", "192"], "explicacao": "32 ÷ 6 = 5, resto 2. Os 2 que sobram precisam de mais uma van: 6.", "tutor": {"alternativas": {"5": "32 ÷ 6 = 5 e sobram 2 alunos, que também precisam de van.", "5,3": "Não existe 0,3 de van: arredonde para cima.", "192": "Você multiplicou em vez de dividir."}, "pontos": ["Em problemas, leia o que o resto significa."], "pegadinha": "O resultado da conta (5) não é a resposta do problema (6)."}}]$j$::jsonb, now()
from turmas t join escolas e on e.id = t.escola_id
where e.codigo = 'PILOTO' and t.nome = '6º ano A'
  and not exists (select 1 from materiais x where x.turma_id = t.id and x.titulo = 'Diagnóstico de largada: Matemática');
insert into materiais (turma_id, autor, materia, titulo, status, questoes, publicado_em)
select t.id, (select tp.professor_id from turma_professores tp where tp.turma_id = t.id limit 1), 'pt', 'Diagnóstico de largada: Português', 'publicado', $j$[{"id": "d1", "tipo": "mc", "habilidade": "Substantivo abstrato", "enunciado": "Na frase \"A <b>alegria</b> da turma contagiou a escola\", qual palavra é um substantivo <b>abstrato</b>?", "resposta": "alegria", "alternativas": ["alegria", "turma", "contagiou", "escola"], "explicacao": "Alegria é um sentimento: substantivo abstrato.", "tutor": {"alternativas": {"turma": "Turma é substantivo concreto (coletivo de alunos).", "contagiou": "É verbo: indica ação.", "escola": "É concreto: nomeia um lugar que existe por si."}, "pontos": ["Abstrato: sentimentos, estados, ações (alegria, saudade, corrida).", "Concreto: seres e coisas que existem por si (escola, fada, gato)."], "pegadinha": "Concreto não é \"o que dá para tocar\": fada e Deus são concretos."}}, {"id": "d2", "tipo": "mc", "habilidade": "Acentuação", "enunciado": "Qual palavra está acentuada <b>corretamente</b>?", "resposta": "lâmpada", "alternativas": ["lâmpada", "ideía", "rúim", "heroi"], "explicacao": "Lâmpada é proparoxítona, e toda proparoxítona leva acento.", "tutor": {"alternativas": {"ideía": "Ideia perdeu o acento no Acordo Ortográfico (ditongo aberto em paroxítona).", "rúim": "Ruim não tem acento: a sílaba forte é \"im\".", "heroi": "Herói precisa de acento: ditongo aberto \"ói\" em oxítona."}, "pontos": ["Toda proparoxítona é acentuada.", "Ideia, assembleia e heroico perderam o acento; herói e papéis mantêm."], "pegadinha": "Ideia sem acento, mas herói com acento: a regra muda conforme a sílaba tônica."}}, {"id": "d3", "tipo": "mc", "habilidade": "Mas × mais", "enunciado": "Qual frase usa \"<b>mas</b>\" corretamente?", "resposta": "Estudei muito, mas a prova estava difícil.", "alternativas": ["Estudei muito, mas a prova estava difícil.", "Eu quero mas sorvete.", "Ela é a mas alta da sala.", "Mas dois alunos chegaram."], "explicacao": "\"Mas\" indica oposição, como \"porém\".", "tutor": {"alternativas": {"Eu quero mas sorvete.": "Aqui é \"mais\" (quantidade).", "Ela é a mas alta da sala.": "Aqui é \"mais\" (intensidade).", "Mas dois alunos chegaram.": "Sentido de quantidade: o certo é \"mais dois\"."}, "pontos": ["Mas = porém (oposição). Mais = quantidade ou intensidade (contrário de menos)."], "pegadinha": "Troque por \"porém\": se fizer sentido, é \"mas\"."}}, {"id": "d4", "tipo": "mc", "habilidade": "Tempos verbais", "enunciado": "Em \"Amanhã nós <b>viajaremos</b> para a praia\", o verbo está no:", "resposta": "futuro do presente", "alternativas": ["futuro do presente", "presente", "pretérito perfeito", "pretérito imperfeito"], "explicacao": "-remos indica futuro: viajaremos.", "tutor": {"alternativas": {"presente": "Presente seria \"viajamos\" (agora).", "pretérito perfeito": "Seria \"viajamos\" com sentido de ontem; a terminação -remos indica futuro.", "pretérito imperfeito": "Seria \"viajávamos\"."}, "pontos": ["Futuro do presente: -rei, -rá, -remos, -rão.", "Pretérito imperfeito: -ava, -ia."], "pegadinha": "A palavra \"amanhã\" ajuda, mas a terminação do verbo é que decide."}}, {"id": "d5", "tipo": "mc", "habilidade": "Sujeito", "enunciado": "Qual é o <b>sujeito</b> em \"Os meninos do bairro jogaram bola\"?", "resposta": "Os meninos do bairro", "alternativas": ["Os meninos do bairro", "bola", "jogaram", "do bairro"], "explicacao": "Quem jogou? Os meninos do bairro.", "tutor": {"alternativas": {"bola": "Bola é o que foi jogado: complemento do verbo.", "jogaram": "É o verbo.", "do bairro": "É só parte do sujeito; o núcleo é \"meninos\"."}, "pontos": ["Para achar o sujeito, pergunte ao verbo: quem?", "O verbo concorda com o núcleo do sujeito (meninos → jogaram)."], "pegadinha": "O sujeito pode ter várias palavras; não pegue só um pedaço."}}, {"id": "d6", "tipo": "mc", "habilidade": "Sentido figurado", "enunciado": "Em \"Ele tem um <b>coração de pedra</b>\", a expressão quer dizer que ele é:", "resposta": "insensível", "alternativas": ["insensível", "muito forte", "doente do coração", "muito pesado"], "explicacao": "Coração de pedra = alguém que não se comove.", "tutor": {"alternativas": {"muito forte": "Pedra aqui não é força: é dureza de sentimentos.", "doente do coração": "É sentido figurado, não literal.", "muito pesado": "A expressão não fala de peso."}, "pontos": ["Sentido figurado: a palavra ganha um significado diferente do literal."], "pegadinha": "Ler ao pé da letra muda totalmente o sentido."}}, {"id": "d7", "tipo": "mc", "habilidade": "Vírgula no vocativo", "enunciado": "Qual frase usa a vírgula corretamente para <b>chamar alguém</b>?", "resposta": "Maria, venha aqui.", "alternativas": ["Maria, venha aqui.", "Maria venha, aqui.", "Maria venha aqui,", "Maria, venha, aqui."], "explicacao": "Vocativo (nome de quem é chamado) se separa com vírgula.", "tutor": {"alternativas": {"Maria venha, aqui.": "A vírgula deve separar o nome de quem é chamado, não o \"aqui\".", "Maria venha aqui,": "Vírgula no fim não separa o vocativo.", "Maria, venha, aqui.": "Tem vírgula a mais entre \"venha\" e \"aqui\"."}, "pontos": ["Vocativo: chama alguém e vem separado por vírgula."], "pegadinha": "\"Vamos comer, vovó\" é diferente de \"Vamos comer vovó\"."}}, {"id": "d8", "tipo": "mc", "habilidade": "Adjetivo", "enunciado": "Em \"O gato <b>preguiçoso</b> dormiu no sofá <b>macio</b>\", quais são os adjetivos?", "resposta": "preguiçoso e macio", "alternativas": ["preguiçoso e macio", "gato e sofá", "dormiu", "o e no"], "explicacao": "Adjetivo dá característica ao substantivo: gato preguiçoso, sofá macio.", "tutor": {"alternativas": {"gato e sofá": "São substantivos: dão nome.", "dormiu": "É verbo.", "o e no": "\"O\" é artigo e \"no\" é preposição + artigo."}, "pontos": ["Adjetivo caracteriza o substantivo.", "Pergunte \"como é?\": como é o gato? Preguiçoso."], "pegadinha": "Na dúvida, veja se a palavra está \"descrevendo\" outra."}}, {"id": "d9", "tipo": "mc", "habilidade": "Gênero textual", "enunciado": "Um texto curto que conta uma história com <b>moral no final</b>, geralmente com animais que falam, é uma:", "resposta": "fábula", "alternativas": ["fábula", "notícia", "receita", "poesia"], "explicacao": "Fábula: animais que falam e uma moral no fim.", "tutor": {"alternativas": {"notícia": "Notícia informa fatos reais e recentes.", "receita": "Receita ensina a fazer algo (texto instrucional).", "poesia": "Poesia é organizada em versos e não precisa ter moral."}, "pontos": ["Fábula: moral. Conto: narrativa curta. Notícia: fato real. Receita: instruções."], "pegadinha": "Lenda e fábula são diferentes: a lenda explica algo pela tradição, sem moral obrigatória."}}, {"id": "d10", "tipo": "mc", "habilidade": "Referência (pronome)", "enunciado": "Em \"A Ana encontrou o irmão e deu <b>a ele</b> um presente\", a palavra \"ele\" se refere a:", "resposta": "o irmão", "alternativas": ["o irmão", "Ana", "o presente", "um amigo"], "explicacao": "\"Ele\" retoma o irmão, para não repetir a palavra.", "tutor": {"alternativas": {"Ana": "Ana é quem deu; e \"ele\" é masculino.", "o presente": "O presente é o que foi dado; \"a ele\" indica quem recebeu.", "um amigo": "Nenhum amigo aparece no texto."}, "pontos": ["Pronomes retomam palavras já ditas e evitam repetição."], "pegadinha": "Procure a palavra anterior que combina em gênero e número."}}]$j$::jsonb, now()
from turmas t join escolas e on e.id = t.escola_id
where e.codigo = 'PILOTO' and t.nome = '6º ano A'
  and not exists (select 1 from materiais x where x.turma_id = t.id and x.titulo = 'Diagnóstico de largada: Português');
