select t.id, (select tp.professor_id from turma_professores tp where tp.turma_id = t.id limit 1), 'en', 'Diagnóstico de largada: Inglês', 'publicado', $j$[{"id": "d1", "tipo": "mc", "habilidade": "Verb to be", "enunciado": "Complete: \"She ___ my sister.\"", "resposta": "is", "alternativas": ["is", "am", "are", "be"], "explicacao": "She → is.", "tutor": {"alternativas": {"am": "Am só se usa com I.", "are": "Are se usa com you, we e they.", "be": "Be é a forma base; na frase, conjuga: she is."}, "pontos": ["I am · he/she/it is · you/we/they are."], "pegadinha": "Não traduza palavra por palavra: em inglês, o to be muda com a pessoa."}}, {"id": "d2", "tipo": "mc", "habilidade": "Plural irregular", "enunciado": "What is the plural of <b>child</b>?", "resposta": "children", "alternativas": ["children", "childs", "childes", "childrens"], "explicacao": "Child → children.", "tutor": {"alternativas": {"childs": "Child tem plural irregular: não leva -s.", "childes": "Não existe; o plural é children.", "childrens": "Children já é plural: não leva -s."}, "pontos": ["Irregulares comuns: man → men, woman → women, tooth → teeth, mouse → mice."], "pegadinha": "Childrens está errado: é colocar dois plurais juntos."}}, {"id": "d3", "tipo": "mc", "habilidade": "Possessivos", "enunciado": "O livro é dele: \"This is ___ book.\"", "resposta": "his", "alternativas": ["his", "her", "he", "him"], "explicacao": "Dele → his.", "tutor": {"alternativas": {"her": "Her é dela.", "he": "He é sujeito (ele), não indica posse.", "him": "Him é objeto (I see him)."}, "pontos": ["my, your, his, her, its, our, their."], "pegadinha": "His (dele) e her (dela) são trocados com frequência."}}, {"id": "d4", "tipo": "mc", "habilidade": "Simple present", "enunciado": "\"He ___ football every Saturday.\"", "resposta": "plays", "alternativas": ["plays", "play", "playing", "played"], "explicacao": "He/she/it + verbo com -s: plays.", "tutor": {"alternativas": {"play": "Com he, she e it, o verbo ganha -s.", "playing": "Faltaria o verbo to be (is playing) e teria outro sentido.", "played": "Played é passado; \"every Saturday\" indica rotina."}, "pontos": ["Simple present: hábitos e rotinas.", "He/she/it → verbo + s (plays, goes, watches)."], "pegadinha": "Esquecer o -s na terceira pessoa é o erro número 1."}}, {"id": "d5", "tipo": "mc", "habilidade": "Dias da semana", "enunciado": "Which day comes <b>after Wednesday</b>?", "resposta": "Thursday", "alternativas": ["Thursday", "Tuesday", "Friday", "Monday"], "explicacao": "Wednesday (quarta) → Thursday (quinta).", "tutor": {"alternativas": {"Tuesday": "Tuesday vem antes de Wednesday.", "Friday": "Friday vem depois de Thursday.", "Monday": "Monday é o começo da semana útil."}, "pontos": ["Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday."], "pegadinha": "Tuesday e Thursday começam com T e são confundidos."}}, {"id": "d6", "tipo": "mc", "habilidade": "There is / there are", "enunciado": "\"___ two cats in the garden.\"", "resposta": "There are", "alternativas": ["There are", "There is", "They are", "It is"], "explicacao": "Dois gatos → there are.", "tutor": {"alternativas": {"There is": "There is é para uma coisa só; aqui são dois gatos.", "They are": "They are descreve; para dizer que algo existe, usa there are.", "It is": "It is também descreve; não indica existência."}, "pontos": ["There is + singular; there are + plural."], "pegadinha": "Em português dizemos \"tem dois gatos\"; em inglês, \"there are\"."}}, {"id": "d7", "tipo": "mc", "habilidade": "Perguntas com do", "enunciado": "\"___ you like pizza?\"", "resposta": "Do", "alternativas": ["Do", "Does", "Are", "Is"], "explicacao": "You → do.", "tutor": {"alternativas": {"Does": "Does é para he, she e it.", "Are": "Like é verbo de ação: a pergunta usa do.", "Is": "Is é to be, para he/she/it."}, "pontos": ["Do: I, you, we, they. Does: he, she, it."], "pegadinha": "Are you like… está errado: com verbo de ação, use do."}}, {"id": "d8", "tipo": "mc", "habilidade": "Falso cognato", "enunciado": "\"<b>Pretend</b>\" em inglês significa:", "resposta": "fingir", "alternativas": ["fingir", "pretender", "prender", "apresentar"], "explicacao": "Pretend = fingir.", "tutor": {"alternativas": {"pretender": "Falso cognato: pretender é \"intend\".", "prender": "Prender é \"arrest\".", "apresentar": "Apresentar é \"present\" ou \"introduce\"."}, "pontos": ["Falsos cognatos parecem português, mas têm outro sentido: pretend, push, parents."], "pegadinha": "Parents são os pais, não os parentes."}}, {"id": "d9", "tipo": "mc", "habilidade": "Preposições", "enunciado": "O livro está em cima da mesa: \"The book is ___ the table.\"", "resposta": "on", "alternativas": ["on", "in", "under", "at"], "explicacao": "Em cima, apoiado → on.", "tutor": {"alternativas": {"in": "In é dentro.", "under": "Under é embaixo.", "at": "At indica um ponto ou lugar, não \"sobre\"."}, "pontos": ["in = dentro · on = sobre · under = embaixo."], "pegadinha": "Em português, \"na mesa\" pode ser dentro ou em cima; em inglês, decida."}}, {"id": "d10", "tipo": "mc", "habilidade": "Horas", "enunciado": "What time is it? <b>7:30</b>", "resposta": "It's half past seven.", "alternativas": ["It's half past seven.", "It's a quarter past seven.", "It's half past eight.", "It's seven thirteen."], "explicacao": "7:30 = half past seven (ou seven thirty).", "tutor": {"alternativas": {"It's a quarter past seven.": "A quarter past é 7:15.", "It's half past eight.": "Seria 8:30.", "It's seven thirteen.": "Thirteen é 13; 30 é thirty."}, "pontos": ["quarter past = :15 · half past = :30 · quarter to = :45."], "pegadinha": "Thirteen (13) e thirty (30) soam parecidos."}}]$j$::jsonb, now()
from turmas t join escolas e on e.id = t.escola_id
where e.codigo = 'PILOTO' and t.nome = '6º ano A'
  and not exists (select 1 from materiais x where x.turma_id = t.id and x.titulo = 'Diagnóstico de largada: Inglês');
insert into materiais (turma_id, autor, materia, titulo, status, questoes, publicado_em)
select t.id, (select tp.professor_id from turma_professores tp where tp.turma_id = t.id limit 1), 'ci', 'Diagnóstico de largada: Ciências', 'publicado', $j$[{"id": "d1", "tipo": "mc", "habilidade": "Célula", "enunciado": "Qual estrutura da célula <b>controla o que entra e sai</b>?", "resposta": "membrana plasmática", "alternativas": ["membrana plasmática", "núcleo", "citoplasma", "parede celular"], "explicacao": "A membrana plasmática é seletiva: escolhe o que entra e sai.", "tutor": {"alternativas": {"núcleo": "O núcleo comanda a célula e guarda o DNA, mas não controla a entrada.", "citoplasma": "O citoplasma é o \"recheio\" onde ficam as organelas.", "parede celular": "A parede só existe em plantas e dá sustentação; quem controla a passagem é a membrana."}, "pontos": ["Membrana: controle. Núcleo: comando e DNA. Citoplasma: recheio."], "pegadinha": "Parede celular também envolve a célula, mas não seleciona."}}, {"id": "d2", "tipo": "mc", "habilidade": "Níveis de organização", "enunciado": "Qual é a ordem correta, do <b>menor para o maior</b>?", "resposta": "célula → tecido → órgão → sistema", "alternativas": ["célula → tecido → órgão → sistema", "tecido → célula → órgão → sistema", "célula → órgão → tecido → sistema", "órgão → sistema → tecido → célula"], "explicacao": "Células formam tecidos; tecidos formam órgãos; órgãos formam sistemas.", "tutor": {"alternativas": {"tecido → célula → órgão → sistema": "A célula é a menor unidade: vem antes do tecido.", "célula → órgão → tecido → sistema": "Órgão é formado por tecidos: o tecido vem antes.", "órgão → sistema → tecido → célula": "A ordem está invertida."}, "pontos": ["Célula → tecido → órgão → sistema → organismo."], "pegadinha": "Pular o tecido é o erro mais comum."}}, {"id": "d3", "tipo": "mc", "habilidade": "Misturas", "enunciado": "Água com óleo forma uma mistura:", "resposta": "heterogênea", "alternativas": ["heterogênea", "homogênea", "pura", "gasosa"], "explicacao": "Água e óleo não se misturam: duas fases → heterogênea.", "tutor": {"alternativas": {"homogênea": "Homogênea teria uma fase só; dá para ver o óleo separado.", "pura": "Substância pura é um material só; aqui são dois.", "gasosa": "Os dois são líquidos."}, "pontos": ["Homogênea: uma fase. Heterogênea: duas ou mais fases visíveis."], "pegadinha": "Água com sal dissolvido é homogênea; água com óleo, heterogênea."}}, {"id": "d4", "tipo": "mc", "habilidade": "Separação de misturas", "enunciado": "Para separar areia da água, o método mais simples é a:", "resposta": "filtração", "alternativas": ["filtração", "destilação", "imantação", "evaporação"], "explicacao": "O filtro segura a areia e deixa a água passar.", "tutor": {"alternativas": {"destilação": "Destilação é para separar líquidos ou sal dissolvido, com aquecimento.", "imantação": "Imantação usa ímã: serve para metais.", "evaporação": "Evaporar a água funcionaria, mas é bem mais lento; e a pergunta é o mais simples."}, "pontos": ["Filtração: sólido não dissolvido + líquido."], "pegadinha": "Sal dissolvido passa pelo filtro; areia, não."}}, {"id": "d5", "tipo": "mc", "habilidade": "Mudanças de estado", "enunciado": "Gotinhas no espelho depois do banho quente são exemplo de:", "resposta": "condensação", "alternativas": ["condensação", "evaporação", "fusão", "solidificação"], "explicacao": "O vapor quente encosta no espelho frio e vira líquido.", "tutor": {"alternativas": {"evaporação": "Evaporação é o contrário: líquido virando vapor.", "fusão": "Fusão é sólido virando líquido.", "solidificação": "Solidificação é líquido virando sólido."}, "pontos": ["Condensação: gás → líquido. Vaporização: líquido → gás."], "pegadinha": "A água estava no ar como vapor; no espelho, ela condensa."}}, {"id": "d6", "tipo": "mc", "habilidade": "Transformação química", "enunciado": "Qual destas é uma <b>transformação química</b>?", "resposta": "queimar papel", "alternativas": ["queimar papel", "derreter gelo", "rasgar papel", "dissolver açúcar"], "explicacao": "Queimar forma substâncias novas (cinza, gases).", "tutor": {"alternativas": {"derreter gelo": "É mudança de estado: continua sendo água (física).", "rasgar papel": "Muda só a forma: física.", "dissolver açúcar": "O açúcar continua lá; dá para recuperar evaporando a água (física)."}, "pontos": ["Química: forma substância nova. Física: muda forma ou estado."], "pegadinha": "Mudança de estado nunca é química."}}, {"id": "d7", "tipo": "mc", "habilidade": "Sistema nervoso", "enunciado": "Qual parte do encéfalo cuida do <b>equilíbrio</b>?", "resposta": "cerebelo", "alternativas": ["cerebelo", "cérebro", "medula espinal", "nervo óptico"], "explicacao": "Cerebelo = equilíbrio e coordenação.", "tutor": {"alternativas": {"cérebro": "O cérebro pensa e decide; o equilíbrio é do cerebelo.", "medula espinal": "A medula conduz mensagens e comanda reflexos.", "nervo óptico": "Leva a imagem do olho ao cérebro."}, "pontos": ["Cérebro: pensar. Cerebelo: equilíbrio. Medula: reflexos."], "pegadinha": "Cérebro e cerebelo têm nomes parecidos."}}, {"id": "d8", "tipo": "mc", "habilidade": "Visão", "enunciado": "Quem tem <b>miopia</b> enxerga mal:", "resposta": "de longe", "alternativas": ["de longe", "de perto", "as cores", "só no escuro"], "explicacao": "Míope vê borrado o que está longe.", "tutor": {"alternativas": {"de perto": "De perto é a hipermetropia.", "as cores": "Não distinguir cores é daltonismo.", "só no escuro": "Não é a definição de miopia."}, "pontos": ["Miopia: longe. Hipermetropia: perto."], "pegadinha": "Troque as duas e erra a questão."}}, {"id": "d9", "tipo": "mc", "habilidade": "Músculos", "enunciado": "O músculo do <b>coração</b> é do tipo:", "resposta": "cardíaco", "alternativas": ["cardíaco", "liso", "esquelético", "voluntário"], "explicacao": "Músculo cardíaco: só no coração, involuntário.", "tutor": {"alternativas": {"liso": "Liso fica em órgãos como estômago e intestino.", "esquelético": "Esquelético move o corpo e é voluntário.", "voluntário": "O coração bate sem você mandar."}, "pontos": ["Esquelético: voluntário. Liso: órgãos. Cardíaco: coração."], "pegadinha": "O coração é involuntário como o liso, mas tem tipo próprio."}}, {"id": "d10", "tipo": "mc", "habilidade": "Rochas", "enunciado": "Em qual tipo de rocha é mais comum encontrar <b>fósseis</b>?", "resposta": "sedimentar", "alternativas": ["sedimentar", "magmática", "metamórfica", "vulcânica"], "explicacao": "Camadas de sedimentos soterram e preservam restos de seres vivos.", "tutor": {"alternativas": {"magmática": "Nasce do magma muito quente: nada se preserva.", "metamórfica": "Calor e pressão destroem os fósseis.", "vulcânica": "É magmática também."}, "pontos": ["Sedimentar: camadas e fósseis. Magmática: magma. Metamórfica: calor e pressão."], "pegadinha": "Mármore é metamórfica; arenito é sedimentar."}}]$j$::jsonb, now()
