select t.id, (select tp.professor_id from turma_professores tp where tp.turma_id = t.id limit 1), 'hi', 'Diagnóstico de largada: História', 'publicado', $j$[{"id": "d1", "tipo": "mc", "habilidade": "Séculos", "enunciado": "O ano <b>1500</b> pertence a qual século?", "resposta": "XV", "alternativas": ["XV", "XVI", "XIV", "V"], "explicacao": "1500 é o último ano do século XV (1401 a 1500).", "tutor": {"alternativas": {"XVI": "Ano terminado em 00 é o último do século, não o primeiro do seguinte.", "XIV": "O século XIV vai de 1301 a 1400.", "V": "Esse é o século 5, mil anos antes."}, "pontos": ["Corte os dois últimos algarismos e some 1. Terminou em 00? Não soma."], "pegadinha": "1500 → XV, não XVI."}}, {"id": "d2", "tipo": "mc", "habilidade": "Datas a.C.", "enunciado": "Qual data é <b>mais antiga</b>?", "resposta": "800 a.C.", "alternativas": ["800 a.C.", "300 a.C.", "100 d.C.", "1500 d.C."], "explicacao": "Antes de Cristo, quanto maior o número, mais antigo.", "tutor": {"alternativas": {"300 a.C.": "Antes de Cristo, número menor é mais perto de nós: mais recente.", "100 d.C.": "Depois de Cristo vem depois de todas as datas a.C.", "1500 d.C.": "É muito mais recente."}, "pontos": ["a.C.: número maior = mais antigo. d.C.: número maior = mais recente."], "pegadinha": "800 a.C. parece \"maior\", mas é mais antigo."}}, {"id": "d3", "tipo": "mc", "habilidade": "Fontes históricas", "enunciado": "Uma entrevista com sua avó sobre a infância dela é uma fonte:", "resposta": "oral", "alternativas": ["oral", "escrita", "material", "iconográfica"], "explicacao": "Alguém contando o que viveu = fonte oral.", "tutor": {"alternativas": {"escrita": "Escrita seria um texto ou carta.", "material": "Material seria um objeto.", "iconográfica": "Iconográfica seria uma imagem."}, "pontos": ["Escrita · oral · iconográfica (imagem) · material (objeto)."], "pegadinha": "Se a entrevista for escrita depois, o texto vira fonte escrita."}}, {"id": "d4", "tipo": "mc", "habilidade": "Pré-história", "enunciado": "A agricultura surgiu em qual período?", "resposta": "Neolítico", "alternativas": ["Neolítico", "Paleolítico", "Idade dos Metais", "Idade Média"], "explicacao": "Neo = novo: o novo jeito de viver foi plantar.", "tutor": {"alternativas": {"Paleolítico": "No Paleolítico, viviam de caça e coleta.", "Idade dos Metais": "A agricultura já existia antes.", "Idade Média": "É muito depois, já na História escrita."}, "pontos": ["Paleolítico: nômades, fogo. Neolítico: agricultura, sedentarização."], "pegadinha": "O fogo é do Paleolítico; a agricultura, do Neolítico."}}, {"id": "d5", "tipo": "mc", "habilidade": "Egito × Mesopotâmia", "enunciado": "A Mesopotâmia ficava entre quais rios?", "resposta": "Tigre e Eufrates", "alternativas": ["Tigre e Eufrates", "Nilo e Jordão", "Amazonas e Negro", "Reno e Danúbio"], "explicacao": "Mesopotâmia = terra entre rios: Tigre e Eufrates.", "tutor": {"alternativas": {"Nilo e Jordão": "O Nilo é do Egito.", "Amazonas e Negro": "São rios do Brasil.", "Reno e Danúbio": "São rios da Europa."}, "pontos": ["Egito: Nilo, pirâmides, hieróglifos. Mesopotâmia: Tigre e Eufrates, cuneiforme, zigurates."], "pegadinha": "Nilo é do Egito, não da Mesopotâmia."}}, {"id": "d6", "tipo": "mc", "habilidade": "Atenas × Esparta", "enunciado": "Qual era o governo de <b>Esparta</b>?", "resposta": "oligarquia", "alternativas": ["oligarquia", "democracia", "monarquia absoluta de um rei persa", "república romana"], "explicacao": "Esparta: poder nas mãos de poucos.", "tutor": {"alternativas": {"democracia": "Democracia era Atenas.", "monarquia absoluta de um rei persa": "Esparta lutou contra os persas.", "república romana": "República é de Roma."}, "pontos": ["Atenas = democracia. Esparta = oligarquia."], "pegadinha": "É a dupla mais cobrada da prova."}}, {"id": "d7", "tipo": "mc", "habilidade": "Democracia ateniense", "enunciado": "Quem podia participar da democracia de Atenas?", "resposta": "homens livres, filhos de atenienses", "alternativas": ["homens livres, filhos de atenienses", "todos os moradores", "mulheres e homens livres", "estrangeiros ricos"], "explicacao": "Só os cidadãos: homens, livres, filhos de atenienses.", "tutor": {"alternativas": {"todos os moradores": "Mulheres, estrangeiros e escravizados ficavam de fora.", "mulheres e homens livres": "Mulheres não participavam.", "estrangeiros ricos": "Estrangeiros não participavam, mesmo ricos."}, "pontos": ["Democracia ateniense: limitada."], "pegadinha": "Não era a democracia de hoje."}}, {"id": "d8", "tipo": "mc", "habilidade": "Guerras gregas", "enunciado": "A Guerra do Peloponeso foi entre:", "resposta": "Atenas e Esparta", "alternativas": ["Atenas e Esparta", "gregos e persas", "Roma e Cartago", "Grécia e Egito"], "explicacao": "Peloponeso: gregos contra gregos.", "tutor": {"alternativas": {"gregos e persas": "Gregos × persas são as Guerras Médicas.", "Roma e Cartago": "São as Guerras Púnicas.", "Grécia e Egito": "Não é essa guerra."}, "pontos": ["Médicas: gregos × persas. Peloponeso: Atenas × Esparta."], "pegadinha": "Atenas venceu as Médicas e perdeu o Peloponeso."}}, {"id": "d9", "tipo": "mc", "habilidade": "Roma: fases", "enunciado": "Qual é a ordem das fases políticas de Roma?", "resposta": "Monarquia → República → Império", "alternativas": ["Monarquia → República → Império", "República → Monarquia → Império", "Monarquia → Império → República", "Império → República → Monarquia"], "explicacao": "Monarquia (753 a.C.) → República (509 a.C.) → Império (27 a.C.).", "tutor": {"alternativas": {"República → Monarquia → Império": "A Monarquia veio primeiro.", "Monarquia → Império → República": "O Império é a última fase.", "Império → República → Monarquia": "Está invertido."}, "pontos": ["M-R-I."], "pegadinha": "Júlio César não foi imperador; o primeiro foi Otávio Augusto."}}, {"id": "d10", "tipo": "mc", "habilidade": "Roma: sociedade", "enunciado": "Na Roma Antiga, os <b>plebeus</b> eram:", "resposta": "a maioria livre: camponeses, artesãos e comerciantes", "alternativas": ["a maioria livre: camponeses, artesãos e comerciantes", "os donos das terras e do poder", "pessoas escravizadas por guerra ou dívida", "dependentes de famílias ricas"], "explicacao": "Plebeus: maioria livre, sem direitos políticos no início.", "tutor": {"alternativas": {"os donos das terras e do poder": "Esses eram os patrícios.", "pessoas escravizadas por guerra ou dívida": "Esses eram os escravos.", "dependentes de famílias ricas": "Esses eram os clientes."}, "pontos": ["Patrícios: elite. Plebeus: maioria. Clientes: dependentes. Escravos: guerra ou dívida."], "pegadinha": "Plebeu era livre; escravo não."}}]$j$::jsonb, now()
