select t.id, (select tp.professor_id from turma_professores tp where tp.turma_id = t.id limit 1), 'ge', 'Diagnóstico de largada: Geografia', 'publicado', $j$[{"id": "d1", "tipo": "mc", "habilidade": "Paisagem", "enunciado": "Uma paisagem com prédios, ruas e plantações é chamada de:", "resposta": "humanizada", "alternativas": ["humanizada", "natural", "intocada", "selvagem"], "explicacao": "Construída ou modificada pelas pessoas = humanizada (cultural).", "tutor": {"alternativas": {"natural": "Natural teria pouca ou nenhuma ação humana.", "intocada": "Intocada é o mesmo que natural.", "selvagem": "Também sugere natural."}, "pontos": ["Natural: sem ação humana. Humanizada: modificada pelas pessoas."], "pegadinha": "Plantação é feita por pessoas: é humanizada."}}, {"id": "d2", "tipo": "mc", "habilidade": "Pontos cardeais", "enunciado": "O Sol nasce aproximadamente no:", "resposta": "leste", "alternativas": ["leste", "oeste", "norte", "sul"], "explicacao": "Nascente = leste. Poente = oeste.", "tutor": {"alternativas": {"oeste": "Oeste é onde o Sol se põe.", "norte": "O Sol não nasce no norte.", "sul": "O Sol não nasce no sul."}, "pontos": ["Leste: nascente. Oeste: poente."], "pegadinha": "É \"aproximadamente\": o ponto exato muda ao longo do ano."}}, {"id": "d3", "tipo": "mc", "habilidade": "Colaterais", "enunciado": "Qual é a direção <b>oposta ao nordeste</b>?", "resposta": "sudoeste", "alternativas": ["sudoeste", "sudeste", "noroeste", "sul"], "explicacao": "Nordeste ↔ sudoeste.", "tutor": {"alternativas": {"sudeste": "Você trocou só uma parte; o oposto troca as duas.", "noroeste": "Noroeste é oposto do sudeste.", "sul": "Sul é oposto do norte."}, "pontos": ["Opostos: N–S, L–O, NE–SO, NO–SE."], "pegadinha": "Trocar só metade do nome."}}, {"id": "d4", "tipo": "mc", "habilidade": "Coordenadas", "enunciado": "Qual linha divide a Terra em hemisfério <b>norte e sul</b>?", "resposta": "Linha do Equador", "alternativas": ["Linha do Equador", "Meridiano de Greenwich", "Trópico de Capricórnio", "Círculo Polar Ártico"], "explicacao": "Equador: paralelo 0°.", "tutor": {"alternativas": {"Meridiano de Greenwich": "Greenwich divide leste e oeste.", "Trópico de Capricórnio": "É um paralelo, mas não divide norte e sul.", "Círculo Polar Ártico": "Fica perto do Polo Norte."}, "pontos": ["Equador: norte × sul (latitude). Greenwich: leste × oeste (longitude)."], "pegadinha": "Equador e Greenwich são trocados com frequência."}}, {"id": "d5", "tipo": "mc", "habilidade": "Latitude × longitude", "enunciado": "A latitude mede a distância a partir do:", "resposta": "Equador", "alternativas": ["Equador", "meridiano de Greenwich", "Polo Norte", "Sol"], "explicacao": "Latitude: 0° no Equador até 90° nos polos.", "tutor": {"alternativas": {"meridiano de Greenwich": "Greenwich é a referência da longitude.", "Polo Norte": "A contagem começa no Equador (0°).", "Sol": "Latitude não tem relação com o Sol."}, "pontos": ["Latitude: N/S, até 90°. Longitude: L/O, até 180°."], "pegadinha": "Latitude ↔ paralelos; longitude ↔ meridianos."}}, {"id": "d6", "tipo": "mc", "habilidade": "Escala", "enunciado": "Qual escala mostra <b>mais detalhes</b>?", "resposta": "1 : 5.000", "alternativas": ["1 : 5.000", "1 : 5.000.000", "1 : 1.000.000", "todas mostram o mesmo"], "explicacao": "Número pequeno depois do 1 : → escala grande → muitos detalhes.", "tutor": {"alternativas": {"1 : 5.000.000": "Número grande: área enorme e pouco detalhe.", "1 : 1.000.000": "Também mostra uma área grande, com pouco detalhe.", "todas mostram o mesmo": "A escala muda muito o nível de detalhe."}, "pontos": ["1 : 5.000 → planta de bairro. 1 : 5.000.000 → mapa do país."], "pegadinha": "\"Escala grande\" mostra área pequena com muito detalhe."}}, {"id": "d7", "tipo": "mc", "habilidade": "Movimentos da Terra", "enunciado": "O movimento que causa o <b>dia e a noite</b> é a:", "resposta": "rotação", "alternativas": ["rotação", "translação", "inclinação do eixo", "órbita da Lua"], "explicacao": "Rotação: giro da Terra em torno de si, em cerca de 24 horas.", "tutor": {"alternativas": {"translação": "Translação é a volta em torno do Sol (um ano).", "inclinação do eixo": "A inclinação explica as estações, não o dia e a noite.", "órbita da Lua": "A Lua não causa dia e noite."}, "pontos": ["Rotação → dia e noite. Translação + inclinação → estações."], "pegadinha": "Rotação = dia; translação = ano."}}, {"id": "d8", "tipo": "mc", "habilidade": "Estações do ano", "enunciado": "As estações acontecem principalmente por causa:", "resposta": "da inclinação do eixo da Terra", "alternativas": ["da inclinação do eixo da Terra", "da distância entre a Terra e o Sol", "da rotação", "das fases da Lua"], "explicacao": "O eixo inclinado faz cada hemisfério receber mais ou menos luz durante o ano.", "tutor": {"alternativas": {"da distância entre a Terra e o Sol": "Se fosse a distância, os dois hemisférios teriam verão juntos, e não têm.", "da rotação": "A rotação causa dia e noite.", "das fases da Lua": "A Lua não causa estações."}, "pontos": ["Estações: inclinação + translação.", "Hemisférios têm estações opostas."], "pegadinha": "A ideia da distância é o erro mais comum."}}, {"id": "d9", "tipo": "mc", "habilidade": "Relevo", "enunciado": "Forma de relevo plana e baixa, onde se acumulam sedimentos:", "resposta": "planície", "alternativas": ["planície", "planalto", "montanha", "depressão"], "explicacao": "Planície: plana, baixa, deposição.", "tutor": {"alternativas": {"planalto": "Planalto é elevado e predomina o desgaste.", "montanha": "Montanha é muito elevada.", "depressão": "Depressão é mais baixa que o entorno, não necessariamente plana com deposição."}, "pontos": ["Planície: deposição. Planalto: desgaste."], "pegadinha": "A diferença não é só a altura: é deposição × desgaste."}}, {"id": "d10", "tipo": "mc", "habilidade": "Tempo × clima", "enunciado": "\"Hoje está chovendo em São José dos Campos.\" Essa frase fala de:", "resposta": "tempo", "alternativas": ["tempo", "clima", "relevo", "estação do ano"], "explicacao": "Tempo = condição do momento.", "tutor": {"alternativas": {"clima": "Clima é o padrão de muitos anos, não o dia de hoje.", "relevo": "Relevo é a forma do terreno.", "estação do ano": "Estação é um período do ano, não a condição de hoje."}, "pontos": ["Tempo: agora. Clima: padrão de muitos anos."], "pegadinha": "Na fala do dia a dia trocamos os dois; na prova, não."}}]$j$::jsonb, now()
